<?php
if (!defined('ABSPATH')) exit;
final class WPFI_Admin {
 private $repo,$scheduler,$importer,$logger; public function __construct($r,$s,$i,$l){$this->repo=$r;$this->scheduler=$s;$this->importer=$i;$this->logger=$l;add_action('admin_menu',[$this,'menu']);add_action('admin_post_wpfi_save_feed',[$this,'save']);add_action('admin_post_wpfi_delete_feed',[$this,'delete']);add_action('admin_post_wpfi_run_feed',[$this,'run']);}
 public function menu(){add_submenu_page('woocommerce','XML Feed Importer','XML Feed Importer','manage_woocommerce','wpfi-feeds',[$this,'page']);}
 private function can(){return current_user_can('manage_woocommerce');} private function url($a=[]){return add_query_arg(array_merge(['page'=>'wpfi-feeds'],$a),admin_url('admin.php'));}
 public function page(){if(!$this->can())return;$a=sanitize_key($_GET['action']??'list');if($a==='edit'||$a==='new')$this->edit();else$this->list();}
 private function list(){echo '<div class="wrap"><h1>XML Product Feeds</h1><p><a class="button button-primary" href="'.esc_url($this->url(['action'=>'new'])).'">Add feed</a> <a class="button" href="'.esc_url($this->url(['action'=>'logs'])).'">View import logs</a></p><table class="widefat striped"><tr><th>Name</th><th>URL</th><th>Authentication</th><th>Schedule</th><th>Actions</th></tr>';foreach($this->repo->all() as $f){$auth=esc_html($f['auth']['type']??'none');echo '<tr><td>'.esc_html($f['name']).'</td><td>'.esc_html($f['url']).'</td><td>'.$auth.'</td><td>'.esc_html($f['frequency']).'</td><td><a href="'.esc_url($this->url(['action'=>'edit','id'=>$f['id']])).'">Edit</a> | <a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=wpfi_run_feed&id='.$f['id']),'wpfi_run_'.$f['id'])).'">Run now</a> | <a onclick="return confirm(\'Delete feed?\')" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=wpfi_delete_feed&id='.$f['id']),'wpfi_delete_'.$f['id'])).'">Delete</a></td></tr>';}echo '</table></div>';}
 private function input($n,$v,$type='text'){return '<input class="regular-text" type="'.$type.'" name="'.esc_attr($n).'" value="'.esc_attr($v??'').'">';}
 private function pairs($a){$o=[];foreach((array)$a as $k=>$v)$o[]=$k.'='.$v;return implode("\n",$o);} private function parse($x){$o=[];foreach(preg_split('/\r\n|\r|\n/',(string)$x) as $l){$p=explode('=', $l,2);if(count($p)===2&&trim($p[0]))$o[sanitize_text_field(trim($p[0]))]=sanitize_text_field(trim($p[1]));}return $o;}
 private function edit(){ $id=sanitize_text_field($_GET['id']??'');$f=wp_parse_args($id?$this->repo->get($id):[],$this->repo->defaults());$a=$f['auth'];echo '<div class="wrap"><h1>'.($id?'Edit':'Add').' XML feed</h1><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="wpfi_save_feed"><input type="hidden" name="id" value="'.esc_attr($f['id']).'">';wp_nonce_field('wpfi_save_feed');echo '<table class="form-table">';foreach([['name','Name'],['slug','Slug'],['url','XML URL'],['product_xpath','Product XPath'],['identifier_field','Identifier field'],['variation_xpath','Variation XPath'],['variation_identifier_field','Variation identifier']] as $x)echo '<tr><th>'.esc_html($x[1]).'</th><td>'.$this->input($x[0],$f[$x[0]]).'</td></tr>';echo '<tr><th>Enabled</th><td><input type="checkbox" name="enabled" value="1" '.checked($f['enabled'],1,false).'></td></tr><tr><th>Frequency</th><td><select name="frequency">';foreach(['wpfi_15m'=>'15 minutes','wpfi_30m'=>'30 minutes','hourly'=>'Hourly','twicedaily'=>'Twice daily','daily'=>'Daily','wpfi_6h'=>'6 hours','weekly'=>'Weekly'] as $k=>$v)echo '<option value="'.$k.'" '.selected($f['frequency'],$k,false).'>'.$v.'</option>';echo '</select></td></tr></table><h2>Request authentication</h2><p>Credentials are stored in WordPress options and are never written to import logs.</p><table class="form-table"><tr><th>Method</th><td><select name="auth_type"><option value="none" '.selected($a['type']??'none','none',false).'>None</option><option value="api_key" '.selected($a['type']??'','api_key',false).'>API key header</option><option value="bearer" '.selected($a['type']??'','bearer',false).'>Bearer token</option><option value="basic" '.selected($a['type']??'','basic',false).'>Basic username/password</option><option value="query" '.selected($a['type']??'','query',false).'>Query-string credentials</option><option value="custom" '.selected($a['type']??'','custom',false).'>Custom headers</option></select></td></tr><tr><th>API key header name</th><td>'.$this->input('api_key_name',$a['api_key_name']??'X-API-Key').'</td></tr><tr><th>API key value</th><td>'.$this->input('api_key',$a['api_key']??'','password').'</td></tr><tr><th>Bearer token</th><td>'.$this->input('bearer_token',$a['bearer_token']??'','password').'</td></tr><tr><th>Username</th><td>'.$this->input('username',$a['username']??'').'</td></tr><tr><th>Password</th><td>'.$this->input('password',$a['password']??'','password').'</td></tr><tr><th>Query parameters</th><td><textarea name="query_params" rows="4" class="large-text code">'.esc_textarea($this->pairs($a['query_params']??[])).'</textarea><p class="description">One key=value per line. Used when Query-string credentials is selected.</p></td></tr><tr><th>Custom headers</th><td><textarea name="headers" rows="4" class="large-text code">'.esc_textarea($this->pairs($a['headers']??[])).'</textarea><p class="description">One Header-Name=value per line.</p></td></tr></table><h2>Mappings</h2><textarea name="map" rows="8" class="large-text code">'.esc_textarea($this->pairs($f['map'])).'</textarea><h2>Attributes</h2><textarea name="attributes" rows="5" class="large-text code">'.esc_textarea($this->pairs($f['attributes'])).'</textarea><h2>Namespaces</h2><textarea name="namespaces" rows="5" class="large-text code">'.esc_textarea($this->pairs($f['namespaces'])).'</textarea><p><button class="button button-primary">Save feed</button> <a class="button" href="'.esc_url($this->url()).'">Cancel</a></p></form></div>';}
 public function save(){if(!$this->can()||!check_admin_referer('wpfi_save_feed'))wp_die('Permission denied.');$f=$this->repo->defaults();$f['id']=sanitize_text_field($_POST['id']??'')?:wp_generate_uuid4();foreach(['name','slug','product_xpath','identifier_field','variation_xpath','variation_identifier_field'] as $k)$f[$k]=sanitize_text_field(wp_unslash($_POST[$k]??''));$f['url']=esc_url_raw(wp_unslash($_POST['url']??''));$f['enabled']=!empty($_POST['enabled'])?1:0;$f['frequency']=sanitize_key($_POST['frequency']??'daily');foreach(['map','attributes','namespaces'] as $k)$f[$k]=$this->parse(wp_unslash($_POST[$k]??''));$f['auth']=['type'=>sanitize_key($_POST['auth_type']??'none'),'api_key_name'=>sanitize_text_field($_POST['api_key_name']??'X-API-Key'),'api_key'=>sanitize_text_field($_POST['api_key']??''),'bearer_token'=>sanitize_text_field($_POST['bearer_token']??''),'username'=>sanitize_text_field($_POST['username']??''),'password'=>sanitize_text_field($_POST['password']??''),'query_params'=>$this->parse(wp_unslash($_POST['query_params']??'')),'headers'=>$this->parse(wp_unslash($_POST['headers']??''))];$this->repo->save($f);$this->scheduler->sync();wp_safe_redirect($this->url(['message'=>'Feed saved.']));exit;}
 public function delete(){ $id=sanitize_text_field($_GET['id']??'');if(!$this->can()||!$id||!check_admin_referer('wpfi_delete_'.$id))wp_die('Permission denied.');$this->repo->delete($id);$this->scheduler->sync();wp_safe_redirect($this->url());exit;}
 public function run(){ $id=sanitize_text_field($_GET['id']??'');if(!$this->can()||!$id||!check_admin_referer('wpfi_run_'.$id))wp_die('Permission denied.');$f=$this->repo->get($id);if($f)$this->importer->import($f);wp_safe_redirect($this->url(['message'=>'Import completed.']));exit;}
}
